23097 +                 var data = imgData.data;
23098 +                 for (var i = 0; i < data.length; i += 4) {
23099 +                     var r = data[i];
23100 +                     var g = data[i+1];
23101 +                     var b = data[i+2];
23102 +                     var a = data[i+3];
