23107 +                             var cx = canvas.width / 2;
23108 +                             var cy = canvas.height / 2;
23109 +                             var dx = x - cx;
23110 +                             var dy = y - cy;
23111 +                             var dist = Math.sqrt(dx*dx + dy*dy);
23112 +                             var maxRadius = Math.min(canvas.width, canvas.height) / 2;
23113 +                             if (dist > maxRadius * 0.85) {
